31	function HistoryScreen({ conversations, onSelect, onNewChat, navigate, onCopyConversation }) {
32	  const formatDate = (d) => {
33	    if (!d) return '';
34	    const date = new Date(d);
35	    const now = new Date();
36	    const diff = now - date;
37	    if (diff < 86400000) return 'Today';
38	    if (diff < 172800000) return 'Yesterday';
39	    return date.toLocaleDateString();
40	  };
41	
42	  return (
43	    <div style={{ height: '100%', overflow: 'auto', background: 'var(--color-surface-2)' }}>
44	      <div style={{ padding: 'var(--space-4)' }}>
45	        <button
46	          type="button"
47	          className="pcp-btn pcp-btn--primary"
48	          style={{ width: '100%', marginBottom: 'var(--space-4)' }}
49	          onClick={() => { onNewChat(); navigate('/'); }}
50	        >
51	          + Start a new chat
52	        </button>
53	      </div>
54	      {conversations.length === 0 ? (
55	        <div style={{ textAlign: 'center', padding: 'var(--space-6)', color: 'var(--color-text-2)' }}>
56	          <p style={{ fontSize: 'var(--font-size-lg)', marginBottom: 'var(--space-3)' }}>No conversations yet</p>
57	          <p style={{ fontSize: 'var(--font-size-base)' }}>Start chatting and your history will appear here.</p>
58	        </div>
59	      ) : (
60	        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)', padding: '0 var(--space-4)' }}>
61	          {conversations.map((c) => (
62	            <div
63	              key={c.id}
64	              className="pcp-card pcp-card--interactive"
65	              style={{ textAlign: 'left', width: '100%' }}
66	            >
67	              <button
68	                type="button"
69	                style={{ all: 'unset', display: 'block', width: '100%', cursor: 'pointer' }}
70	                onClick={() => { onSelect(c.id); navigate('/'); }}
71	              >
72	                <div style={{ fontSize: 'var(--font-size-base)', fontWeight: 'var(--font-weight-medium)', color: 'var(--color-text-1)', marginBottom: 'var(--space-1)' }}>
73	                  {c.context_summary || c.preview || c.task_type || 'Chat session'}
74	                </div>
75	                <div style={{ fontSize: 'var(--font-size-sm)', color: 'var(--color-text-2)', display: 'flex', justifyContent: 'space-between' }}>
76	                  <span>{formatDate(c.started_at || c.created_at)}</span>
77	                  <span style={{ color: c.status === 'active' ? 'var(--color-success)' : 'var(--color-text-3)' }}>
78	                    {c.status === 'active' ? '\u25CF Active' : 'Ended'}
79	                  </span>
80	                </div>
81	              </button>
82	              <button
83	                type="button"
84	                className="pcp-btn pcp-btn--ghost"
85	                style={{
86	                  marginTop: 'var(--space-2)',
87	                  fontSize: 'var(--font-size-xs)',
88	                  padding: 'var(--space-1) var(--space-2)',
89	                  color: 'var(--color-primary)',
90	                  border: '1px solid var(--color-primary)',
91	                  borderRadius: 'var(--radius-md)',
92	                  background: 'transparent',
93	                  cursor: 'pointer',
94	                }}
95	                onClick={(e) => { e.stopPropagation(); onCopyConversation(c.id); }}
96	                aria-label={`Copy conversation: ${c.context_summary || c.preview || 'Chat session'}`}
97	              >
98	                Copy conversation
99	              </button>
100	            </div>
101	          ))}
102	        </div>
103	      )}
104	    </div>
105	  );
106	}
