1	// RoleContext — provides { role, setRole, activeLearner, setActiveLearner, learners }
2	// Role detection: a user is a "helper" if they have an active buddy pair where
3	// they are the helper. Otherwise they are a "learner".
4	import React, { createContext, useContext, useState, useMemo, useCallback } from 'react';
5	
6	const RoleContext = createContext(null);
7	
8	/**
9	 * Detect role from buddy data.
10	 * A user is a "helper" if buddyPair exists and currentUserId === buddyPair.helper_id.
11	 */
12	function detectRole(buddyPair, currentUserId) {
13	  if (!buddyPair || !currentUserId) return 'learner';
14	  if (buddyPair.helper_id === currentUserId) return 'helper';
15	  return 'learner';
16	}
17	
18	/**
19	 * Build learner list from buddy pair data for the helper's perspective.
20	 */
21	function buildLearnerList(buddyPair, currentUserId) {
22	  if (!buddyPair || !currentUserId) return [];
23	  if (buddyPair.helper_id !== currentUserId) return [];
24	
25	  return [
26	    {
27	      id: buddyPair.learner_id,
28	      name: buddyPair.learner_name || 'Learner',
29	      status: 'offline',
30	      statusLabel: 'Offline',
31	    },
32	  ];
33	}
34	
35	export function RoleProvider({ children }) {
36	  const [role, setRole] = useState('learner'); // 'learner' | 'helper'
37	  const [activeLearner, setActiveLearner] = useState(null);
38	  const [learners, setLearners] = useState([]);
39	
40	  /**
41	   * detectAndApplyRole — call this when buddy data or user data changes.
42	   * Automatically sets role and builds the learner list.
43	   */
44	  const detectAndApplyRole = useCallback((buddyPair, currentUserId) => {
45	    const detected = detectRole(buddyPair, currentUserId);
46	    setRole(detected);
47	
48	    if (detected === 'helper') {
49	      const list = buildLearnerList(buddyPair, currentUserId);
50	      setLearners(list);
51	
52	      // Restore active learner from localStorage or default to first
53	      const stored = localStorage.getItem('pcp-active-learner');
54	      const match = list.find((l) => l.id === stored);
55	      setActiveLearner(match || list[0] || null);
56	    } else {
57	      setLearners([]);
58	      setActiveLearner(null);
59	    }
60	  }, []);
61	
62	  /**
63	   * switchLearner — switch the active learner context (for multi-learner helpers).
64	   */
65	  const switchLearner = useCallback(
66	    (learnerId) => {
67	      const found = learners.find((l) => l.id === learnerId);
68	      if (found) {
69	        setActiveLearner(found);
70	        localStorage.setItem('pcp-active-learner', learnerId);
71	      }
72	    },
73	    [learners]
74	  );
75	
76	  const value = useMemo(
77	    () => ({
78	      role,
79	      setRole,
80	      activeLearner,
81	      setActiveLearner,
82	      learners,
83	      detectAndApplyRole,
84	      switchLearner,
85	    }),
86	    [role, activeLearner, learners, detectAndApplyRole, switchLearner]
87	  );
88	
89	  return (
90	    <RoleContext.Provider value={value}>
91	      {children}
92	    </RoleContext.Provider>
93	  );
94	}
95	
96	// eslint-disable-next-line react-refresh/only-export-components
97	export function useRole() {
98	  const ctx = useContext(RoleContext);
99	  if (!ctx) {
100	    throw new Error('useRole must be used within a RoleProvider');
