12	 */
13	export function useChat(userId) {
14	  const [messages, setMessages] = useState([]);
15	  const [isConnected, setIsConnected] = useState(false);
16	  const [isTyping, setIsTyping] = useState(false);
17	  const [connectionFailed, setConnectionFailed] = useState(false);
18	  const [activeSequence, setActiveSequence] = useState(null);
19	  const [welcomeBack, setWelcomeBack] = useState(null);
20	  const [conversationId, setConversationId] = useState(null);
21	  const [feedbackPrompt, setFeedbackPrompt] = useState(null);
22	  const [agentConnected, setAgentConnected] = useState(false);
23	  // Standalone terminal history (user's own terminal panel)
24	  const [terminalHistory, setTerminalHistory] = useState([]);
25	  const [terminalCwd, setTerminalCwd] = useState(null);
26	  // Buddy session state — set when THIS user is observing a learner's session
27	  const [buddySession, setBuddySession] = useState(null);
28	  // Set when a buddy is observing OUR session (we are the learner)
29	  const [buddyObserving, setBuddyObserving] = useState(null);
30	
31	  const wsRef = useRef(null);
32	  const reconnectTimeoutRef = useRef(null);
33	  const messageIdRef = useRef(0);
34	  const reconnectAttemptsRef = useRef(0);
35	  const connectRef = useRef(null);
36	  const conversationIdRef = useRef(null);
37	
38	  const nextId = () => {
39	    messageIdRef.current += 1;
40	    return messageIdRef.current;
41	  };
42	
43	  // Keep a ref in sync so callbacks can read the latest conversation id
44	  // without being re-created on every change.
45	  useEffect(() => {
46	    conversationIdRef.current = conversationId;
47	  }, [conversationId]);
48	
49	  const connect = useCallback(() => {
50	    if (!userId) return;
51	
52	    // Determine WS URL: use relative path so Vite proxy handles it
53	    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
54	    const wsUrl = `${protocol}//${window.location.host}/ws`;
55	
56	    const ws = new WebSocket(wsUrl);
57	    wsRef.current = ws;
58	
59	    ws.onopen = () => {
60	      setIsConnected(true);
61	      setConnectionFailed(false);
62	      reconnectAttemptsRef.current = 0;
63	      // Send init message so the server knows who we are
64	      const browserSystemInfo = collectBrowserSystemInfo();
65	      ws.send(JSON.stringify({ type: 'init', userId, browserSystemInfo }));
66	    };
67	
68	    ws.onmessage = (event) => {
69	      let data;
70	      try {
71	        data = JSON.parse(event.data);
72	      } catch {
73	        console.error('PC Pal: invalid JSON from server', event.data);
74	        return;
75	      }
76	
77	      switch (data.type) {
78	        case 'init_ack':
79	          if (data.conversationId) {
80	            setConversationId(data.conversationId);
81	          }
82	          break;
83	
84	        case 'welcome_back':
85	          setWelcomeBack({
86	            reviewSkills: data.reviewSkills || [],
87	            pendingHelp: data.pendingHelp || [],
88	          });
89	          break;
90	
91	        case 'typing':
92	          setIsTyping(true);
93	          break;
94	
95	        case 'response':
96	          setIsTyping(false);
97	          setMessages((prev) => [
98	            ...prev,
99	            {
100	              id: nextId(),
101	              role: 'assistant',
102	              text: data.text ?? '',
103	              timestamp: new Date().toISOString(),
104	              safetyAlert: data.safetyAlert ?? null,
105	              stepSequence: data.stepSequence || null,
106	              images: data.images || null,
107	              videos: data.videos || null,
108	              guide: data.guide || null,
109	              findings: data.findings || null,
110	              practice: data.practice || null,
111	              screenshot: data.screenshot || null,
112	              confidence: data.confidence || null,
113	            },
114	          ]);
115	          if (data.stepSequence) {
116	            if (data.stepSequence.completed) {
117	              setActiveSequence(null);
118	            } else {
119	              setActiveSequence(data.stepSequence);
120	            }
121	          }
122	          if (data.conversationId) {
123	            setConversationId(data.conversationId);
124	          }
125	          if (data.endedConversationId) {
126	            setFeedbackPrompt({ conversationId: data.endedConversationId });
127	          }
128	          break;
129	
130	        case 'resources':
131	          setIsTyping(false);
132	          setMessages((prev) => [
133	            ...prev,
134	            {
135	              id: nextId(),
136	              role: 'assistant',
137	              text: data.text ?? '',
138	              timestamp: new Date().toISOString(),
139	              resources: data.resources || null,
140	            },
141	          ]);
142	          break;
143	
144	        case 'command_result':
145	          // Update the command result in the most recent message's guide
146	          setMessages((prev) => {
147	            const updated = [...prev];
148	            // Find the latest assistant message with a guide
149	            for (let i = updated.length - 1; i >= 0; i--) {
150	              if (updated[i].guide) {
151	                updated[i] = {
152	                  ...updated[i],
153	                  commandResults: {
154	                    ...(updated[i].commandResults || {}),
155	                    [data.command]: { output: data.output, running: false, error: data.error },
156	                  },
157	                };
158	                break;
159	              }
160	            }
161	            return updated;
162	          });
163	          break;
164	
165	        case 'pair_result':
166	          if (data.success) {
167	            setAgentConnected(true);
168	          }
169	          // The callback is handled via pairAgent below
170	          break;
171	
172	        case 'agent_status':
173	          setAgentConnected(!!data.connected);
174	          break;
175	
176	        case 'new_chat_ack':
177	          // Server created a fresh session after closing the previous one
178	          setMessages([]);
179	          setActiveSequence(null);
180	          setFeedbackPrompt(null);
181	          if (data.conversationId) {
182	            setConversationId(data.conversationId);
183	          }
184	          break;
185	
186	        case 'chat_ended':
187	          // User clicked "End chat". Server confirmed the session is closed;
188	          // show the feedback modal.
189	          if (data.conversationId) {
190	            setFeedbackPrompt({ conversationId: data.conversationId });
191	          }
192	          break;
193	
194	        case 'error':
195	          setIsTyping(false);
196	          setMessages((prev) => [
197	            ...prev,
198	            {
199	              id: nextId(),
200	              role: 'assistant',
201	              text: data.message ?? 'Something went wrong. Please try again.',
202	              timestamp: new Date().toISOString(),
203	              safetyAlert: null,
204	            },
205	          ]);
206	          break;
207	
208	        case 'terminal_result':
209	          setTerminalHistory(prev => prev.map(entry =>
210	            entry.requestId === data.requestId
211	              ? { ...entry, output: data.output, error: data.error, running: false }
212	              : entry
213	          ));
214	          if (data.cwd) setTerminalCwd(data.cwd);
215	          break;
216	
217	        // ─── Buddy session messages ───
218	        case 'buddy_join_ack':
219	          setBuddySession({
220	            learnerId: data.learnerId,
221	            learnerName: data.learnerName,
222	            messages: (data.messages || []).map((m, i) => ({ ...m, id: 'bh_' + i })),
