224	          });
225	          break;
226	
227	        case 'buddy_chat_forward':
228	          setBuddySession(prev => prev ? {
229	            ...prev,
230	            messages: [...prev.messages, { id: 'bf_' + Date.now(), role: data.role, text: data.text, timestamp: data.timestamp }],
231	          } : prev);
232	          break;
233	
234	        case 'buddy_command_result':
235	          setBuddySession(prev => {
236	            if (!prev) return prev;
237	            return {
238	              ...prev,
239	              cwd: data.cwd || prev.cwd,
240	              terminalHistory: prev.terminalHistory.map(entry =>
241	                entry.requestId === data.requestId
242	                  ? { ...entry, output: data.output, error: data.error, running: false }
243	                  : entry
244	              ),
245	            };
246	          });
247	          break;
248	
249	        case 'buddy_joined':
250	          setBuddyObserving({ buddyName: data.buddyName });
251	          break;
252	
253	        case 'buddy_left':
254	          setBuddyObserving(null);
255	          break;
256	
257	        case 'buddy_terminal_start':
258	          // Learner sees buddy starting a command
259	          setMessages(prev => [...prev, {
260	            id: 'bt_' + data.requestId,
261	            role: 'assistant',
262	            text: `${data.buddyName} is running a diagnostic command...`,
263	            timestamp: new Date().toISOString(),
264	            buddyTerminal: { requestId: data.requestId, command: data.command, output: '', error: false, running: true, buddyName: data.buddyName },
265	          }]);
266	          break;
267	
268	        case 'buddy_terminal_result':
269	          // Update the pending terminal message with the result
270	          setMessages(prev => prev.map(m =>
271	            m.buddyTerminal && m.buddyTerminal.requestId === data.requestId
272	              ? { ...m, text: `${data.buddyName} ran: ${data.command}`, buddyTerminal: { ...m.buddyTerminal, output: data.output, error: data.error, running: false } }
273	              : m
274	          ));
275	          break;
276	
277	        default:
278	          console.warn('PC Pal: unknown message type', data.type);
279	      }
280	    };
281	
282	    ws.onclose = () => {
283	      setIsConnected(false);
284	      setIsTyping(false);
285	      const attempts = reconnectAttemptsRef.current;
286	      if (attempts >= 5) {
287	        setConnectionFailed(true);
288	        return;
289	      }
290	      reconnectAttemptsRef.current = attempts + 1;
291	      const delay = Math.min(1000 * Math.pow(2, attempts), 30000);
292	      reconnectTimeoutRef.current = setTimeout(() => connectRef.current?.(), delay);
293	    };
294	
295	    ws.onerror = (err) => {
296	      console.error('PC Pal WebSocket error', err);
297	      ws.close();
298	    };
299	  }, [userId]);
300	
301	  // Keep the ref in sync so ws.onclose can call the latest connect without
302	  // capturing it as a const (which would be a temporal dead zone violation).
303	  useLayoutEffect(() => {
304	    connectRef.current = connect;
305	  });
306	
307	  useEffect(() => {
308	    if (!userId) return;
309	    connect();
310	
311	    return () => {
312	      clearTimeout(reconnectTimeoutRef.current);
313	      if (wsRef.current) {
314	        // Remove the onclose handler before closing so we don't trigger reconnect
315	        wsRef.current.onclose = null;
316	        wsRef.current.close();
317	      }
318	    };
319	  }, [userId, connect]);
320	
321	  /**
322	   * Send a chat message.
323	   * @param {string} text
324	   */
325	  const sendMessage = useCallback(
326	    (text) => {
327	      const trimmed = text.trim();
328	      if (!trimmed) return;
329	
330	      // Optimistically add the user's message to the list
331	      setMessages((prev) => [
332	        ...prev,
333	        {
334	          id: nextId(),
335	          role: 'user',
336	          text: trimmed,
337	          timestamp: new Date().toISOString(),
338	          safetyAlert: null,
339	        },
340	      ]);
341	
342	      if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
343	        wsRef.current.send(JSON.stringify({ type: 'chat', text: trimmed }));
344	      } else {
345	        console.warn('PC Pal: WebSocket not open, message not sent');
346	        setMessages((prev) => [
347	          ...prev,
348	          {
349	            id: nextId(),
350	            role: 'assistant',
351	            text: 'Sorry, the connection was lost. Please refresh the page and try again.',
352	            timestamp: new Date().toISOString(),
353	            safetyAlert: null,
354	          },
355	        ]);
356	      }
357	    },
358	    [],
359	  );
360	
361	  const dismissWelcomeBack = useCallback(() => setWelcomeBack(null), []);
362	
363	  /**
364	   * Pair with a relay agent using a code. Calls back with { success, message }.
365	   */
366	  const pairAgent = useCallback((code, callback) => {
367	    if (!wsRef.current || wsRef.current.readyState !== WebSocket.OPEN) {
368	      callback({ success: false, message: 'Not connected to PC Pal server.' });
369	      return;
370	    }
371	    // Listen for the pair result
372	    const handler = (event) => {
373	      let data;
374	      try { data = JSON.parse(event.data); } catch { return; }
375	      if (data.type === 'pair_result') {
376	        wsRef.current.removeEventListener('message', handler);
377	        if (data.success) setAgentConnected(true);
378	        callback(data);
379	      }
380	    };
381	    wsRef.current.addEventListener('message', handler);
382	    wsRef.current.send(JSON.stringify({ type: 'pair_agent', code }));
383	  }, []);
384	
385	  /**
386	   * Gather resources (videos + links) related to the conversation.
387	   * Optionally takes extra text from the input field for context.
388	   */
389	  const gatherResources = useCallback((extraText) => {
390	    if (!wsRef.current || wsRef.current.readyState !== WebSocket.OPEN) return;
391	    setIsTyping(true);
392	    // Add a user message showing what was requested
393	    const displayText = extraText
394	      ? `Find resources about: ${extraText}`
395	      : 'Find resources related to our conversation';
396	    setMessages((prev) => [
397	      ...prev,
398	      { id: nextId(), role: 'user', text: displayText, timestamp: new Date().toISOString() },
399	    ]);
400	    wsRef.current.send(JSON.stringify({
401	      type: 'gather_resources',
402	      text: extraText || '',
403	    }));
404	  }, []);
405	
406	  /**
407	   * Run a user-approved command from a guide artifact.
408	   * Sets the command as "running" immediately, then sends to server.
409	   */
410	  const runCommand = useCallback((command) => {
411	    if (!command) return;
412	    // Mark as running in the most recent guide
413	    setMessages((prev) => {
414	      const updated = [...prev];
415	      for (let i = updated.length - 1; i >= 0; i--) {
416	        if (updated[i].guide) {
417	          updated[i] = {
418	            ...updated[i],
419	            commandResults: {
420	              ...(updated[i].commandResults || {}),
421	              [command]: { output: '', running: true, error: false },
422	            },
423	          };
424	          break;
425	        }
426	      }
427	      return updated;
428	    });
429	    // Send to server
430	    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
431	      wsRef.current.send(JSON.stringify({ type: 'run_command', command }));
432	    }
433	  }, []);
434	
435	  /**
436	   * Start a fresh conversation. Closes the current session server-side
437	   * and creates a new one. The server replies with `new_chat_ack`.
438	   */
439	  const startNewChat = useCallback(() => {
440	    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
441	      wsRef.current.send(JSON.stringify({ type: 'new_chat' }));
442	    }
443	  }, []);
444	
445	  /**
446	   * Trigger the end-of-chat flow. Tells the server to close the session;
447	   * the server replies with `chat_ended` and the hook opens the modal.
448	   */
449	  const endChat = useCallback(() => {
450	    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
451	      wsRef.current.send(JSON.stringify({ type: 'end_chat' }));
452	    } else if (conversationIdRef.current) {
453	      // WS not open — fall back to opening the modal locally so the user
454	      // can still leave feedback. The POST below will still persist it.
455	      setFeedbackPrompt({ conversationId: conversationIdRef.current });
456	    }
457	  }, []);
458	
459	  /**
460	   * Reset local state after the server has closed a conversation.
461	   */
462	  const resetChatLocally = useCallback(() => {
463	    setMessages([]);
464	    setActiveSequence(null);
465	    setConversationId(null);
466	    setFeedbackPrompt(null);
467	  }, []);
468	
469	  /**
470	   * POST the rating + optional comment to /api/quality/feedback.
471	   * On success, resets local state so the next message starts a fresh chat.
472	   * @param {{ rating: number, comment?: string }} payload
473	   */
474	  const submitFeedback = useCallback(async ({ rating, comment }) => {
475	    const target = feedbackPrompt?.conversationId;
476	    if (!target || !userId) {
477	      resetChatLocally();
478	      return { ok: false, error: 'missing_context' };
479	    }
480	    try {
481	      const res = await fetch('/api/quality/feedback', {
482	        method: 'POST',
483	        headers: { 'Content-Type': 'application/json' },
484	        body: JSON.stringify({
485	          conversationId: target,
486	          userId,
487	          rating,
488	          comment: comment || null,
489	        }),
490	      });
491	      if (!res.ok) {
492	        const body = await res.json().catch(() => ({}));
493	        console.error('PC Pal: feedback POST failed', res.status, body);
494	        return { ok: false, error: body.error || `http_${res.status}` };
495	      }
496	    } catch (err) {
497	      console.error('PC Pal: feedback POST threw', err);
498	      return { ok: false, error: 'network' };
499	    }
500	    resetChatLocally();
501	    return { ok: true };
502	  }, [feedbackPrompt, userId, resetChatLocally]);
503	
504	  /**
505	   * User dismissed the feedback modal — POST to /skip so the session closes
506	   * cleanly without recording a rating.
507	   */
508	  const skipFeedback = useCallback(async () => {
509	    const target = feedbackPrompt?.conversationId;
510	    if (target && userId) {
511	      try {
512	        await fetch('/api/quality/feedback/skip', {
513	          method: 'POST',
514	          headers: { 'Content-Type': 'application/json' },
515	          body: JSON.stringify({ conversationId: target, userId }),
516	        });
517	      } catch (err) {
518	        console.error('PC Pal: feedback skip POST threw', err);
519	      }
520	    }
521	    resetChatLocally();
522	  }, [feedbackPrompt, userId, resetChatLocally]);
523	
524	  const terminalCmdIdRef = useRef(0);
525	  const sendTerminalCommand = useCallback((command) => {
526	    const trimmed = command.trim();
527	    if (!trimmed) return;
528	    terminalCmdIdRef.current += 1;
529	    const requestId = 'tcmd_' + terminalCmdIdRef.current + '_' + Date.now();
530	    setTerminalHistory(prev => [...prev, { requestId, command: trimmed, output: '', error: false, running: true }]);
531	    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
532	      wsRef.current.send(JSON.stringify({ type: 'terminal_command', command: trimmed, requestId }));
533	    }
534	  }, []);
535	
536	  const joinBuddySession = useCallback((learnerId) => {
537	    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
538	      wsRef.current.send(JSON.stringify({ type: 'buddy_join', learnerId }));
539	    }
540	  }, []);
541	
542	  const leaveBuddySession = useCallback((learnerId) => {
543	    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN && learnerId) {
544	      wsRef.current.send(JSON.stringify({ type: 'buddy_leave', learnerId }));
545	    }
546	    setBuddySession(null);
547	  }, []);
548	
