1	import React, { useState, useCallback, useRef, useEffect } from 'react';
2	import './PairingFlow.css';
3	
4	/**
5	 * PairingFlow -- Enter buddy code to pair (D5 section 10).
6	 *
7	 * 6-box code input with auto-advance, backspace goes back, paste fills all.
8	 *
9	 * Props:
10	 *   learnerName   - string (if known from the code preview)
11	 *   onConnect     - (code: string) => Promise<void>
12	 *   onBack        - () => void
13	 *   onNoCode      - () => void
14	 *   isLoading     - boolean
15	 *   error         - string | null
16	 */
17	
18	const CODE_LENGTH = 6;
19	
20	function PairingFlow({
21	  learnerName,
22	  onConnect,
23	  onBack,
24	  onNoCode,
25	  isLoading = false,
26	  error = null,
27	}) {
28	  const [digits, setDigits] = useState(Array(CODE_LENGTH).fill(''));
29	  const inputRefs = useRef([]);
30	
31	  // Ensure refs array is the right size
32	  useEffect(() => {
33	    inputRefs.current = inputRefs.current.slice(0, CODE_LENGTH);
34	  }, []);
35	
36	  const focusInput = useCallback((index) => {
37	    if (inputRefs.current[index]) {
38	      inputRefs.current[index].focus();
39	    }
40	  }, []);
41	
42	  const handleChange = useCallback(
43	    (index, value) => {
44	      // Only allow alphanumeric
45	      const char = value.replace(/[^a-zA-Z0-9]/g, '').toUpperCase().slice(-1);
46	      const newDigits = [...digits];
47	      newDigits[index] = char;
48	      setDigits(newDigits);
49	
50	      // Auto-advance
51	      if (char && index < CODE_LENGTH - 1) {
52	        focusInput(index + 1);
53	      }
54	    },
55	    [digits, focusInput]
56	  );
57	
58	  const handleKeyDown = useCallback(
59	    (index, e) => {
60	      if (e.key === 'Backspace') {
61	        if (!digits[index] && index > 0) {
62	          // Move back on empty backspace
63	          const newDigits = [...digits];
64	          newDigits[index - 1] = '';
65	          setDigits(newDigits);
66	          focusInput(index - 1);
67	          e.preventDefault();
68	        } else {
69	          // Clear current
70	          const newDigits = [...digits];
71	          newDigits[index] = '';
72	          setDigits(newDigits);
73	        }
74	      } else if (e.key === 'ArrowLeft' && index > 0) {
75	        focusInput(index - 1);
76	      } else if (e.key === 'ArrowRight' && index < CODE_LENGTH - 1) {
77	        focusInput(index + 1);
78	      }
79	    },
80	    [digits, focusInput]
81	  );
82	
83	  const handlePaste = useCallback(
84	    (e) => {
85	      e.preventDefault();
86	      const pasted = (e.clipboardData.getData('text') || '')
87	        .replace(/[^a-zA-Z0-9]/g, '')
88	        .toUpperCase()
89	        .slice(0, CODE_LENGTH);
90	
91	      if (pasted.length > 0) {
92	        const newDigits = Array(CODE_LENGTH).fill('');
93	        for (let i = 0; i < pasted.length; i++) {
94	          newDigits[i] = pasted[i];
95	        }
96	        setDigits(newDigits);
