import React, { useRef, useEffect, useState } from 'react';
import { useSpeech } from '../../hooks/useSpeech';
import './MessageInput.css';

/**
 * MessageInput — text input + send button + resources button + mic.
 *
 * - Large input field (min 56px height)
 * - Mic button (only shown when SpeechRecognition is supported) lets users
 *   dictate their question instead of typing.
 * - Submits on Enter (Shift+Enter adds a newline)
 * - Disabled while isTyping
 */
function MessageInput({ onSend, onGatherResources, isTyping }) {
  const inputRef = useRef(null);
  const { recognitionSupported, isListening, startListening, stopListening, stopSpeaking } = useSpeech();
  const [voiceError, setVoiceError] = useState('');

  useEffect(() => {
    if (inputRef.current) inputRef.current.focus();
  }, []);

  useEffect(() => {
    if (!isTyping && inputRef.current) inputRef.current.focus();
  }, [isTyping]);

  const handleSend = () => {
    const text = inputRef.current?.value ?? '';
    if (!text.trim() || isTyping) return;
    onSend(text);
    if (inputRef.current) inputRef.current.value = '';
  };

  const handleResources = () => {
    if (isTyping) return;
    const text = inputRef.current?.value ?? '';
    onGatherResources(text.trim());
    if (inputRef.current) inputRef.current.value = '';
  };

  const handleMic = () => {
    if (isTyping) return;
    setVoiceError('');
    if (isListening) {
      stopListening();
      return;
    }
    // If read-aloud is mid-utterance, the synthesized voice would feed back
    // into the microphone. Cancel any active speech before listening.
    stopSpeaking();
    const ok = startListening(
      (transcript) => {
        if (inputRef.current) {
          inputRef.current.value = transcript;
          inputRef.current.focus();
        }
      },
      () => { /* onEnd handled internally */ }
    );
    if (!ok) {
      setVoiceError("Microphone isn't available right now.");
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="message-input-bar">
      <label htmlFor="chat-input" className="sr-only">
        Type your message
      </label>
      <input
        id="chat-input"
        ref={inputRef}
        type="text"
        className="message-input-field"
        placeholder={isListening ? 'Listening — speak now...' : 'Type your question here...'}
        disabled={isTyping}
        onKeyDown={handleKeyDown}
        autoComplete="off"
        aria-label="Type your question here"
      />
      {recognitionSupported && (
        <button
          type="button"
          className={`message-mic-btn ${isListening ? 'message-mic-btn--listening' : ''}`}
          onClick={handleMic}
          disabled={isTyping}
          aria-label={isListening ? 'Stop listening' : 'Speak your question'}
          aria-pressed={isListening}
          title={isListening ? 'Stop listening' : 'Speak your question'}
        >
          {isListening ? '● Listening' : '🎤 Speak'}
        </button>
      )}
      <button
        className="message-resources-btn"
        onClick={handleResources}
        disabled={isTyping}
        aria-label="Get external help on this topic"
        title="Get external help"
      >
        Get External Help
      </button>
      <button
        className="message-send-btn btn-primary"
        onClick={handleSend}
        disabled={isTyping}
        aria-label="Send message"
      >
        Send
      </button>
      {voiceError && (
        <p className="message-input-bar__error" role="alert">{voiceError}</p>
      )}
    </div>
  );
}

export default MessageInput;

