.a11y-bar {
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
  flex-wrap: wrap;
  padding: var(--spacing-sm) var(--spacing-lg);
  background-color: var(--color-surface-alt);
  border-bottom: 1px solid var(--color-border);
  font-size: var(--font-size-sm);
}

.a11y-bar__label {
  font-weight: 700;
  color: var(--color-text-light);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 0.85em;
}

.a11y-bar__group {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-sm);
}

.a11y-bar__readout {
  font-weight: 600;
  color: var(--color-text);
  min-width: 7ch;
  text-align: center;
}

.a11y-bar__btn {
  min-height: 36px;
  min-width: 44px;
  padding: 4px 10px;
  font-size: var(--font-size-sm);
  font-weight: 700;
  background-color: var(--color-surface);
  color: var(--color-text);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  cursor: pointer;
}

.a11y-bar__btn:hover:not(:disabled) {
  background-color: var(--color-primary-light);
  border-color: var(--color-primary);
}

.a11y-bar__btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.a11y-bar__toggle {
  min-height: 36px;
  padding: 4px 14px;
  font-size: var(--font-size-sm);
  font-weight: 600;
  background-color: var(--color-surface);
  color: var(--color-text);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  cursor: pointer;
}

.a11y-bar__toggle--on {
  background-color: var(--color-primary);
  color: var(--color-white);
  border-color: var(--color-primary-dark);
}

.a11y-bar__toggle:hover {
  border-color: var(--color-primary);
}

@media (max-width: 600px) {
  .a11y-bar {
    gap: var(--spacing-sm);
    padding: var(--spacing-sm);
  }
  .a11y-bar__label {
    display: none;
  }
}

